const express = require('express');
const crypto = require('crypto');
const { Buffer } = require('buffer');

const app = express();
app.use(express.json());

// Secure token store
const API_SECRET = crypto.randomBytes(32);
const sessions = new Map();
const userData = new Map();

// Helper to derive a salted scrypt hash for a password
function hashPassword(password, salt) {
  return crypto.scryptSync(password, salt, 64);
}

// Store per-user credentials (salt + scrypt hash) separately from profile data
const credentials = new Map();
function registerUser(username, password) {
  const salt = crypto.randomBytes(16);
  const hash = hashPassword(password, salt);
  credentials.set(username, { salt, hash });
}

// Initialize some test data
userData.set('admin', { role: 'admin', balance: 1000000, secret: 'flag{s3cr3t_admin_data}' });
userData.set('user1', { role: 'user', balance: 100, secret: 'nothing special' });

// Initialize credentials for test data
registerUser('admin', crypto.randomBytes(24).toString('hex'));
registerUser('user1', crypto.randomBytes(24).toString('hex'));

// HMAC-based token generation
function generateToken(userId, expiresAt) {
  const payload = Buffer.from(JSON.stringify({ sub: userId, exp: expiresAt }));
  const signature = crypto.createHmac('sha256', API_SECRET)
    .update(payload)
    .digest();
  return payload.toString('base64url') + '.' + signature.toString('base64url');
}

// Constant-time comparison utility
function safeCompare(a, b) {
  // Ensure both are buffers for timing-safe comparison
  const bufA = Buffer.isBuffer(a) ? a : Buffer.from(String(a));
  const bufB = Buffer.isBuffer(b) ? b : Buffer.from(String(b));

  if (bufA.length !== bufB.length) {
    return false;
  }
  return crypto.timingSafeEqual(bufA, bufB);
}

// Verify a supplied password against stored scrypt hash in constant time
function verifyPassword(username, password) {
  const cred = credentials.get(username);
  if (!cred || typeof password !== 'string') return false;
  let derived;
  try {
    derived = hashPassword(password, cred.salt);
  } catch (e) {
    return false;
  }
  return safeCompare(derived, cred.hash);
}

// Token verification
function verifyToken(token) {
  if (!token || typeof token !== 'string') return null;

  const parts = token.split('.');
  if (parts.length !== 2) return null;

  const [payloadB64, signatureB64] = parts;

  let payload;
  try {
    payload = Buffer.from(payloadB64, 'base64url');
  } catch (e) {
    return null;
  }

  const expectedSig = crypto.createHmac('sha256', API_SECRET)
    .update(payload)
    .digest();

  let providedSig;
  try {
    providedSig = Buffer.from(signatureB64, 'base64url');
  } catch (e) {
    return null;
  }

  // Verify signature length matches expected HMAC output
  if (providedSig.length !== 32) {
    return null;
  }

  // Use our safe comparison
  if (!safeCompare(expectedSig, providedSig)) {
    return null;
  }

  try {
    const data = JSON.parse(payload.toString());
    if (data.exp && data.exp < Date.now()) return null;
    return data;
  } catch (e) {
    return null;
  }
}

// Authentication middleware
function authenticate(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader) return res.status(401).json({ error: 'No token' });

  const token = authHeader.replace('Bearer ', '');
  const decoded = verifyToken(token);

  if (!decoded) return res.status(401).json({ error: 'Invalid token' });

  req.user = decoded;
  next();
}

// Login endpoint
app.post('/login', (req, res) => {
  const { username, password } = req.body;

  // Require both username and a matching password hash before issuing a token
  if (!username || !userData.has(username) || !verifyPassword(username, password)) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const expiresAt = Date.now() + 3600000; // 1 hour
  const token = generateToken(username, expiresAt);
  sessions.set(username, { token, expiresAt });

  res.json({ token, expiresAt });
});

// Protected resource
app.get('/api/profile', authenticate, (req, res) => {
  const data = userData.get(req.user.sub);
  if (!data) return res.status(404).json({ error: 'User not found' });
  res.json({ username: req.user.sub, ...data });
});

// Admin endpoint
app.get('/api/admin/secrets', authenticate, (req, res) => {
  if (req.user.sub !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }
  const data = userData.get('admin');
  res.json(data);
});

// Token refresh with delegation
app.post('/api/token/delegate', authenticate, (req, res) => {
  const { targetUser, scope } = req.body;

  // Allow creating a delegated token for another user
  // Only admins should be able to delegate
  const requester = userData.get(req.user.sub);
  if (!requester || requester.role !== 'admin') {
    return res.status(403).json({ error: 'Only admins can delegate' });
  }

  if (!targetUser || !userData.has(targetUser)) {
    return res.status(400).json({ error: 'Invalid target user' });
  }

  const expiresAt = Date.now() + 1800000; // 30 min
  const token = generateToken(targetUser, expiresAt);
  res.json({ delegatedToken: token, targetUser, expiresAt });
});

app.listen(3000);
module.exports = app;
